function groupSlices(d){const values=new Map(opportunitySummary(d.r.end).included.map(e=>[e.p.id,e.record.cents/1000000]));const key=pieMode==='stage'?'stage':'bu',groups=new Map();for(const p of opportunityAt(d.r.end).map(e=>e.p)){const name=p[key]||'未分类';if(!groups.has(name))groups.set(name,[]);groups.get(name).push(p)}let gs=[...groups].map(([name,projects],i)=>({name,projects,value:pieMeasure==='amount'?projects.reduce((n,p)=>n+(values.get(p.id)||0),0):projects.length,color:pieMode==='stage'?stateColors[name]||colors[i%6]:{'医卫':'#5b9cf1','党政':'#a69bca','金融':'#5bb7a5','教育':'#e0b575','企业':'#8cabbe','其他':'#c2c8d1'}[name]||colors[i%6]}));gs=gs.filter(g=>g.value>0);if(gs.length>6){gs.sort((a,b)=>b.value-a.value);const others=gs.splice(5);gs.push({name:'其他',projects:others.flatMap(g=>g.projects),value:others.reduce((s,g)=>s+g.value,0),color:'#c3c9d1',members:others.map(g=>g.name)})}return gs}
