function lineSVG(bins,series){const w=900,h=350,l=chartMode==='finance'?65:42,r=21,t=28,b=40,max=Math.max(chartMode==='projects'?4:0,niceMax(Math.max(0,...bins.flatMap(d=>series.map(s=>d[s.key]))))),ph=h-t-b,space=w-l-r,x=i=>bins.length===1?l+space/2:l+i*space/Math.max(1,bins.length-1),y=n=>t+ph-ph*n/max;
 return {w,h,l,r,t,b,max,x,y,html:`<svg id="line-chart" preserveAspectRatio="none" viewBox="0 0 ${w} ${h}" role="group" aria-label="交互趋势图，左右方向键选择日期，回车查看项目" tabindex="0"><defs><linearGradient id="chart-wash" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3687f5" stop-opacity=".065"/><stop offset="1" stop-color="#3687f5" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3,4].map(i=>`<g><line x1="${l}" y1="${y(max*i/4)}" x2="${w-r}" y2="${y(max*i/4)}" stroke="#edf0f4" stroke-dasharray="3 5"/><text x="${l-14}" y="${y(max*i/4)+4}" text-anchor="end" fill="#a5aab4" font-size="11">${num(max*i/4)}</text></g>`).join('')}${series.map((s,j)=>`${j===0&&bins.length>1?`<polygon fill="url(#chart-wash)" points="${x(0)},${y(0)} ${bins.map((b,i)=>`${x(i)},${y(b[s.key])}`).join(' ')} ${x(bins.length-1)},${y(0)}"/>`:''}<polyline class="chart-series" data-series="${s.key}" points="${bins.map((b,i)=>`${x(i)},${y(b[s.key])}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>${bins.length===1?`<circle cx="${x(0)}" cy="${y(bins[0][s.key])}" r="4" fill="${s.color}"/>`:''}`).join('')}${bins.filter((d,i)=>bins.length<=12||i%Math.ceil(bins.length/8)===0||i===bins.length-1).map(d=>`<text x="${x(bins.indexOf(d))}" y="${h-12}" text-anchor="middle" fill="#9ca3af" font-size="11">${d.label}</text>`).join('')}<g id="line-hover" visibility="hidden"><line id="line-ruler" x1="0" y1="${t}" x2="0" y2="${h-b}" stroke="#a6b3c9" stroke-dasharray="4 4"/>${series.map(s=>`<circle id="hover-${s.key}" r="5" fill="white" stroke="${s.color}" stroke-width="2.5"/>`).join('')}</g><rect id="line-hit" x="${l}" y="${t}" width="${w-l-r}" height="${ph}" fill="transparent"/></svg>`}}
function polar(cx,cy,r,a){const rad=a*Math.PI/180;return [cx+r*Math.cos(rad),cy+r*Math.sin(rad)]}
function arcPath(start,end,outer=109,inner=80){const a=polar(150,150,outer,start),b=polar(150,150,outer,end),c=polar(150,150,inner,end),d=polar(150,150,inner,start),large=end-start>180?1:0;return `M${a} A${outer},${outer} 0 ${large} 1 ${b} L${c} A${inner},${inner} 0 ${large} 0 ${d} Z`}
